import subprocess, itertools, collections, random
for n in (2,4,6):
  edges=[(i,j) for i in range(n) for j in range(i+1,n)]
  D=len(edges); cnt=[0]*(D+1)
  for mask in range(1<<D):
    m=mask.bit_count()
    if m<n-1: continue
    adj=[[] for _ in range(n)]
    for e,(u,v) in enumerate(edges):
      if mask>>e&1: adj[u].append(v); adj[v].append(u)
    dist=[-1]*n; dist[0]=0; dq=collections.deque([0])
    while dq:
      u=dq.popleft()
      for v in adj[u]:
        if dist[v]<0: dist[v]=dist[u]+1; dq.append(v)
    if any(x<0 for x in dist): continue
    if sum(x%2==0 for x in dist)*2==n: cnt[m]+=1
  for mod in (998244353, 924844033, 100000007):
