    exp=[x%mod for x in cnt[n-1:]]
    if out"'!=exp:
      print('"'FAIL',n,mod); print(exp); print(out); raise SystemExit
  print('n',n,'counts',cnt[n-1:])
print('abc389_g small brute OK')
